{
  "findings": [
    {
      "check_id": "CKV_AWS_157",
      "title": "Ensure that RDS instances have Multi-AZ enabled",
      "resource": "aws_db_instance.levelup-rds",
      "severity": "MEDIUM",
      "explanation": "The RDS instance does not have Multi-AZ enabled, which reduces availability and resilience in case of an AZ failure."
    },
    {
      "check_id": "CKV_AWS_129",
      "title": "Ensure that respective logs of Amazon Relational Database Service (Amazon RDS) are enabled",
      "resource": "aws_db_instance.levelup-rds",
      "severity": "MEDIUM",
      "explanation": "Logging is not enabled for the RDS instance, which can hinder troubleshooting and compliance monitoring."
    },
    {
      "check_id": "CKV_AWS_226",
      "title": "Ensure DB instance gets all minor upgrades automatically",
      "resource": "aws_db_instance.levelup-rds",
      "severity": "MEDIUM",
      "explanation": "Automatic minor version upgrades are not enabled, which may leave the database vulnerable to known issues."
    },
    {
      "check_id": "CKV_AWS_118",
      "title": "Ensure that enhanced monitoring is enabled for Amazon RDS instances",
      "resource": "aws_db_instance.levelup-rds",
      "severity": "MEDIUM",
      "explanation": "Enhanced monitoring is not enabled, which limits visibility into database performance and health."
    },
    {
      "check_id": "CKV_AWS_353",
      "title": "Ensure that RDS instances have performance insights enabled",
      "resource": "aws_db_instance.levelup-rds",
      "severity": "MEDIUM",
      "explanation": "Performance Insights is not enabled, which can make it harder to analyze and optimize database performance."
    }
  ],
  "patched_code": "resource \"aws_db_instance\" \"levelup-rds\" {\n  identifier = \"${var.ENVIRONMENT}-levelup-rds\"\n  allocated_storage = var.LEVELUP_RDS_ALLOCATED_STORAGE\n  storage_type = \"gp2\"\n  engine = var.LEVELUP_RDS_ENGINE\n  engine_version = var.LEVELUP_RDS_ENGINE_VERSION\n  instance_class = var.DB_INSTANCE_CLASS\n  backup_retention_period = var.BACKUP_RETENTION_PERIOD\n  publicly_accessible = var.PUBLICLY_ACCESSIBLE\n  username = var.LEVELUP_RDS_USERNAME\n  password = var.LEVELUP_RDS_PASSWORD\n  vpc_security_group_ids = [aws_security_group.levelup-rds-sg.id]\n  db_subnet_group_name = aws_db_subnet_group.levelup-rds-subnet-group.name\n  multi_az = true\n  enabled_cloudwatch_logs_exports = [\"error\", \"general\", \"slowquery\", \"audit\"]\n  auto_minor_version_upgrade = true\n  monitoring_interval = 60\n  performance_insights_enabled = true\n}",
  "fix_summary": "Enabled Multi-AZ for high availability, enabled CloudWatch logs for better observability, set auto_minor_version_upgrade to true for automatic updates, enabled enhanced monitoring, and enabled Performance Insights for performance analysis."
}
